import{_ as e,o as t,c as a,ag as o}from"./chunks/framework.D5hoimZQ.js";const d=JSON.parse('{"title":"🔬 科学快报 | 2026年8月1日（事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-08-01.md","filePath":"science-log/src/reconstructed/2026-08-01.md"}'),n={name:"science-log/src/reconstructed/2026-08-01.md"};function s(g,r,i,l,c,p){return t(),a("div",null,[...r[0]||(r[0]=[o('<h1 id="🔬-科学快报-2026年8月1日-事后重建版" tabindex="-1">🔬 科学快报 | 2026年8月1日（事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年8月1日-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年8月1日（事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-06 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 ｜ 重建日：2026-11-06 取证备注：<strong>2026-08-01 为周六，CrossRef 显示 Nature / Science / PNAS 当日 0 条命中</strong>（PNAS 与 Springer Nature 的 issue 日期均落在工作日）。因此科学 5 篇取自「当日及前 3 日出版窗口 2026-07-29 ~ 2026-08-01」真实命中；AI 5 篇取自 arXiv <code>cat:cs.AI</code> submittedDate [202608010000 TO 202608012359] 真实命中。所有 DOI / arXiv 编号均为检索返回值，未做任何补写。</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🦠-痘病毒「门户复合体」首次拿到原位结构" tabindex="-1">🦠 痘病毒「门户复合体」首次拿到原位结构 <a class="header-anchor" href="#🦠-痘病毒「门户复合体」首次拿到原位结构" aria-label="Permalink to &quot;🦠 痘病毒「门户复合体」首次拿到原位结构&quot;">​</a></h3><p><strong>In situ structure of the poxvirus portal complex</strong><em>Nature (2026)</em></p><p>研究用冷冻电子断层扫描（cryo-ET）结合子断层平均与结构预测，首次解出牛痘病毒（vaccinia，痘病毒原型的）核心壁上的<strong>门户复合体</strong>原位结构。该六聚体由 <strong>E8、E6、L3</strong> 三种在痘病毒科中保守、且对感染建立期 mRNA 释放必需的蛋白组成：<strong>E6</strong> 构成门户中央腔并与周围核心壁接触，<strong>E8 六聚体</strong>贴附在 E6 外侧，<strong>L3</strong> 以「二聚体的六聚体」形式结合在内侧。研究进一步显示，基因组释放所需的病毒解旋酶 <strong>D5</strong> 在感染过程中停靠到门户复合体的外侧 E8 边缘，从而与细胞质核心结合。作者指出，这一结构为抗痘病毒（含天花、猴痘）药物设计提供了明确靶点。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10856-2" target="_blank" rel="noreferrer">10.1038/s41586-026-10856-2</a></p><hr><h3 id="⚛️-数字控制的硅量子处理单元-54-个量子点、最多-18-个交换型量子比特" tabindex="-1">⚛️ 数字控制的硅量子处理单元：54 个量子点、最多 18 个交换型量子比特 <a class="header-anchor" href="#⚛️-数字控制的硅量子处理单元-54-个量子点、最多-18-个交换型量子比特" aria-label="Permalink to &quot;⚛️ 数字控制的硅量子处理单元：54 个量子点、最多 18 个交换型量子比特&quot;">​</a></h3><p><strong>A digitally controlled silicon quantum processing unit</strong><em>Nature (2026)</em></p><p>研究提出一个完整的硅基量子处理单元：定制低温 CMOS 控制器 + 高密度超导带状电缆 + 低噪声交换型（exchange-only）量子比特器件。量子芯片是 <strong>54 个交换耦合量子点的三轨阵列</strong>，可配置承载<strong>最多 18 个交换型量子比特</strong>。交换型量子比特之所以被看好，是因为它只用交换相互作用、控制信号简单，且与成熟半导体制造工艺兼容；此前的疑问集中在噪声能否压得足够低、以及布线/控制能否规模化。该工作的贡献正是用「控制器—互连—器件」三层共同设计来回应这两个疑问，作者名单长达 256 人，属大型联合工程。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10754-7" target="_blank" rel="noreferrer">10.1038/s41586-026-10754-7</a></p><hr><h3 id="🌊-首个全光「光子时间晶体」-等离激元超材料在太赫兹频段跑起来" tabindex="-1">🌊 首个全光「光子时间晶体」：等离激元超材料在太赫兹频段跑起来 <a class="header-anchor" href="#🌊-首个全光「光子时间晶体」-等离激元超材料在太赫兹频段跑起来" aria-label="Permalink to &quot;🌊 首个全光「光子时间晶体」：等离激元超材料在太赫兹频段跑起来&quot;">​</a></h3><p><strong>Plasmonic metamaterial time crystal</strong><em>Nature (2026)</em>（预印本 arXiv:2510.02845）</p><p>研究在太赫兹频段用<strong>表面等离激元腔超材料</strong>实现了首个全光光子时间晶体（photonic time crystal, PTC）——即光学性质在<strong>与光周期可比的时间尺度</strong>上被周期性调制的介质。关键在于用<strong>场致载流子动能与有效质量的动态调制</strong>（质量变化最高达静止质量的 80%）实现<strong>接近单位强度、且在亚光周期内相干</strong>的周期驱动。光谱测量显示，体系经一个**奇异点（exceptional point）**进入 PTC 相：两个 Floquet 驱动的光学本征模在此合并。进入该相后，<strong>涌现增益把等离激元损耗压低 50% 以上</strong>，作者据此预测等离激元激光已进入实验可达范围。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10825-9" target="_blank" rel="noreferrer">10.1038/s41586-026-10825-9</a></p><hr><h3 id="🧬-美洲首批天花古基因组-一条已灭绝的、1296-年分家的谱系" tabindex="-1">🧬 美洲首批天花古基因组：一条已灭绝的、1296 年分家的谱系 <a class="header-anchor" href="#🧬-美洲首批天花古基因组-一条已灭绝的、1296-年分家的谱系" aria-label="Permalink to &quot;🧬 美洲首批天花古基因组：一条已灭绝的、1296 年分家的谱系&quot;">​</a></h3><p><strong>The genomic identity of early smallpox in South America</strong><em>Science (2026)</em></p><p>天花是欧洲接触后美洲人口崩溃的主要驱动力之一，但致病毒株的遗传身份此前不明。研究从智利北部两名<strong>印加—殖民时期个体</strong>（约 <strong>1492—1631 CE</strong>）中取出美洲<strong>首批天花古基因组</strong>，它们构成一条<strong>现已灭绝的谱系</strong>，约在 <strong>1296 CE</strong> 分化——时点在中世纪早期欧洲毒株分开之后、现代天花（variola）谱系出现之前。这为「天花随欧洲殖民传入美洲」提供了直接的分子证据。研究还刻画出病毒演化节律：直到 16 世纪晚期<strong>基因失活速率恒定</strong>，随后进入受约束阶段、替换速率再度回升，把 variola 的演化与人类人口学、流行病学的重大转折连在一起。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.aee6957" target="_blank" rel="noreferrer">10.1126/science.aee6957</a></p><hr><h3 id="🧪-用氟化钾做-appel-氟化-把「不能做」的反应变成催化对映选择性路线" tabindex="-1">🧪 用氟化钾做 Appel 氟化：把「不能做」的反应变成催化对映选择性路线 <a class="header-anchor" href="#🧪-用氟化钾做-appel-氟化-把「不能做」的反应变成催化对映选择性路线" aria-label="Permalink to &quot;🧪 用氟化钾做 Appel 氟化：把「不能做」的反应变成催化对映选择性路线&quot;">​</a></h3><p><strong>Catalytic Appel fluorination of alcohols with potassium fluoride</strong><em>Science (2026)</em></p><p>Appel 卤化是把醇变烷基卤的常用反应，却长期不能用来制备<strong>烷基氟</strong>——因为氟会被「扣押」成二氟膦烷而退出反应路径。研究引入<strong>台面稳定的新戊氧基膦盐（neopentoxyphosphonium salts）<strong>破解这一僵局：在</strong>氢键相转移催化</strong>下，多种醇可与<strong>氟化钾（KF）<strong>直接发生氟化，并进而给出</strong>对映选择性氟化</strong>的路径。机理上新戊氧基<strong>氟膦烷</strong>中间体与醇底物发生<strong>可逆交换</strong>，且优先于二氟膦烷生成；催化剂同时帮助 KF 溶解与 P—F 键解离，使烷氧基膦中间体得以走向产物。由牛津大学 Gouverneur 团队与计算化学（Paton）合作完成。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.aec6298" target="_blank" rel="noreferrer">10.1126/science.aec6298</a></p><hr><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🏗️-cadir-让-llm-生成的-cad-程序跨后端可编辑" tabindex="-1">🏗️ CADIR：让 LLM 生成的 CAD 程序跨后端可编辑 <a class="header-anchor" href="#🏗️-cadir-让-llm-生成的-cad-程序跨后端可编辑" aria-label="Permalink to &quot;🏗️ CADIR：让 LLM 生成的 CAD 程序跨后端可编辑&quot;">​</a></h3><p><strong>CADIR: A Cross-Backend Editable Intermediate Representation for Agentic CAD Generation</strong><em>arXiv (2026)</em></p><p>大模型已能从自然语言或图像生成可执行的计算机辅助设计（CAD）程序，但现有做法要么把建模过程写成<strong>绑定单一后端的顺序脚本</strong>（依赖关系隐式）、要么只输出<strong>静态几何</strong>，因此难以同时保住建造历史、稳定的拓扑引用与特征级可编辑性。CADIR 是一个「对智能体友好」的可执行中间表示：它基于 OCCT 几何内核（经 OCP），提供显式、可组合的建模操作与细粒度执行诊断；执行时把建模操作、参数依赖、约束与拓扑选择记录进<strong>构造图</strong>，从而支持跨后端重放与编辑。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.00891" target="_blank" rel="noreferrer">2608.00891</a></p><hr><h3 id="📐-等向性悬崖-llm-做选择的几何指纹" tabindex="-1">📐 等向性悬崖：LLM 做选择的几何指纹 <a class="header-anchor" href="#📐-等向性悬崖-llm-做选择的几何指纹" aria-label="Permalink to &quot;📐 等向性悬崖：LLM 做选择的几何指纹&quot;">​</a></h3><p><strong>Isotropy Cliffs: The Geometric Signature of Decision-Making in Large Language Models</strong><em>arXiv (2026)</em></p><p>研究从「等向性（isotropy）」这一表征几何量切入多选题问答：分析五个开放权重模型、多套数据集后发现存在<strong>决策临界层</strong>——等向性在此发生跃变，同时伴随一次大的表征变化与任务相关簇的涌现。这种同步的几何行为与下游准确率<strong>强相关（r≈0.84）</strong>，且对提示变化稳健，提示它反映的是模型决策的<strong>一般性机制</strong>，而非某条提示的偶然效应。作者因此把它视为可解释性上的一个新观测量：不必读 logits，只看表征几何就能定位「模型在哪里做决定」。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.00828" target="_blank" rel="noreferrer">2608.00828</a></p><hr><h3 id="⚖️-人机协作的「缩放悖论」" tabindex="-1">⚖️ 人机协作的「缩放悖论」 <a class="header-anchor" href="#⚖️-人机协作的「缩放悖论」" aria-label="Permalink to &quot;⚖️ 人机协作的「缩放悖论」&quot;">​</a></h3><p><strong>The Scaling Paradox in Human-AI Collaboration</strong><em>arXiv (2026)</em></p><p>缩放律让人相信「AI 越大越好」，但现实里 AI 很少单独工作。该工作用解析模型考察：AI 的缩放收益何时能传导为人机<strong>联合系统</strong>的表现提升。结论是——<strong>只要人类对 AI 能力的感知准确</strong>，联合表现确实随 AI 规模正向增长；而一旦感知失真，关系会被根本改变：<strong>当人类高估 AI 能力时，会出现「缩放悖论」</strong>，更强的 AI 反而拖低联合表现（因为人会更早把判断权让出去）。这把「模型能力」与「人机系统的可靠性」拆成了两个独立问题。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.00818" target="_blank" rel="noreferrer">2608.00818</a></p><hr><h3 id="🩺-大模型提升医师准确率-却也制造「假性信赖」" tabindex="-1">🩺 大模型提升医师准确率，却也制造「假性信赖」 <a class="header-anchor" href="#🩺-大模型提升医师准确率-却也制造「假性信赖」" aria-label="Permalink to &quot;🩺 大模型提升医师准确率，却也制造「假性信赖」&quot;">​</a></h3><p><strong>Large language models improve physician accuracy but lead to false reliance</strong><em>arXiv (2026)</em></p><p>检索增强大模型承诺「有出处」的临床支持，但其价值取决于证据是<strong>引导</strong>还是<strong>扭曲</strong>医师的依赖。作者构建智能体式检索增强系统 <strong>CORA</strong>：它在基准上保持性能，并在训练数据截止后才发表的病例上取得更大增益。46 名医师的研究中，诊断准确率从<strong>无辅助 70.8% 升到 82.6%</strong>；有正确引用支持时答案更可能正确（87.7% vs 65.5%）。但引用带来<strong>不对称效应</strong>：看似有支持的正确建议采纳率从 34% 升至 76.9%，而<strong>当错误答案看起来有引用支持时，医师的抵制率从 92% 跌到 34.8%</strong>。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.00817" target="_blank" rel="noreferrer">2608.00817</a></p><hr><h3 id="🧰-agentslabench-把智能体评测从「跑分」变成「资源画像」" tabindex="-1">🧰 AgentSLABench：把智能体评测从「跑分」变成「资源画像」 <a class="header-anchor" href="#🧰-agentslabench-把智能体评测从「跑分」变成「资源画像」" aria-label="Permalink to &quot;🧰 AgentSLABench：把智能体评测从「跑分」变成「资源画像」&quot;">​</a></h3><p><strong>AgentSLABench: Evaluating and Benchmarking Agentic Systems Under Resource Constraints</strong><em>arXiv (2026)</em></p><p>现有智能体基准大多只报准确率。AgentSLABench 是资源感知的评测框架：在<strong>声明 CPU / 内存 / 时间 / 网络预算</strong>的 <strong>16 个任务环境</strong>（6 大类，5 个核心任务为多跳问答、零售替换、代码生成、网页购物、旅行规划，另 11 个为扩展任务）中，用隔离 Docker 容器、SHA256 封存的测试集与标准化 profiling 协议，同时测量正确性、延迟、成本、算力、内存与网络。它为每个智能体在每个任务上产出<strong>多维剖面</strong>——像 <code>perf</code>/<code>pprof</code> 剖代码那样剖智能体，只是把「任务正确性」也升为一等维度；论文对 ReAct、PlanAndSolve、Reflexion、CoT、Random 五个通用基线做了画像。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.00805" target="_blank" rel="noreferrer">2608.00805</a></p><hr><blockquote><p>📅 日期：2026-08-01 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇 🗂️ 期号：（第 ? 期 · 事后重建版）——当日无简讯，期号无法从 README 往期目录可靠推算，故不填精确期号</p></blockquote>',55)])])}const u=e(n,[["render",s]]);export{d as __pageData,u as default};
